     "cl.push({text:'결과 보고(내부 결재)',indent:0,completed:true,completedAt:ago(1),result:{text:'결재 완료'}});cl.push({text:'종결 및 기록물 편철',indent:0,completed:false,deadline:D(25)});app.allData.workflows.unshift({id:8951,type:'manual',title:'종합감사 처리절차',checklist:cl,date:'2026. 9. 1.',createdAt:ago(45),deadline:D(30),folderPath:''});wf().checklist.forEach(it=>app.ensureChecklistItemId(it));"
